// Generated by scripts/generateBuildInfo.ts, which runs as part of
// `npm run initial` (and therefore `build`, `exe` and `prestart`), so a
// packaged binary carries the release tag and the commit it was cut from.
//
// This committed copy is the fallback: it keeps tsc, jest and a hand-started
// `node src/server.ts` working without a build step, and it is what an
// untagged local build reports.
export const BUILD_INFO = {
  version: 'dev',
  gitHash: 'unknown',
  buildDate: null as string | null
}
